import type {
  SplitButtonProps,
  SplitButtonLeadingProps,
  SplitButtonTrailingProps,
  SplitButtonMenuContentProps,
  SplitButtonMenuItemProps,
} from "./split-button.types";

import React, { forwardRef } from "react";
import { clsx } from "clsx";
import { useTheme } from "@theme";
import { Button } from "@components/button";
import { Menu } from "@components/menu";
import { ChevronDown } from "@exp-textura/icons";

import { StyledSplitButton, SplitButtonClasses } from "./split-button.styles";

const getSplitButtonChildren = (
  children: React.ReactNode,
): {
  leading: React.ReactElement | null;
  trailing: React.ReactElement | null;
  menuContent: React.ReactElement | null;
} => {
  let leading: React.ReactElement | null = null;
  let trailing: React.ReactElement | null = null;
  let menuContent: React.ReactElement | null = null;

  React.Children.forEach(children, (child) => {
    if (React.isValidElement(child)) {
      const displayName = (child.type as { displayName?: string }).displayName;
      if (displayName === SplitButtonLeading.displayName) {
        leading = child;
      } else if (displayName === SplitButtonTrailing.displayName) {
        trailing = child;
      } else if (displayName === SplitButtonMenuContent.displayName) {
        menuContent = child;
      }
    }
  });

  return { leading, trailing, menuContent };
};

const SplitButtonRoot = forwardRef<HTMLDivElement, SplitButtonProps>(
  (
    {
      children,
      className,
      variant = "default",
      size = "default",
      disabled = false,
      side = "bottom",
      sideOffset = 4,
      align = "end",
      alignOffset = 0,
      menuVariant,
      ...props
    },
    ref,
  ) => {
    const theme = useTheme();
    const rootClasses = clsx(SplitButtonClasses.root, className, {
      [SplitButtonClasses.sm]: size === "sm",
    });

    const { leading, trailing, menuContent } = getSplitButtonChildren(children);

    if (!leading && !trailing && !menuContent) {
      return null;
    }

    const leadingWithProps =
      leading &&
      React.cloneElement(leading, {
        variant,
        size,
        disabled: disabled || leading.props.disabled,
        className: SplitButtonClasses.leading,
      });

    const trailingWithProps =
      trailing &&
      React.cloneElement(trailing, {
        variant,
        size,
        disabled: disabled || trailing.props.disabled,
        className: SplitButtonClasses.trailing,
      });

    const menuContentWithProps = menuContent && <Menu.Content {...menuContent.props} />;

    return (
      <StyledSplitButton
        ref={ref}
        className={rootClasses}
        currentTheme={theme}
        variant={variant}
        {...props}
      >
        {leadingWithProps}
        <Menu
          align={align}
          alignOffset={alignOffset}
          side={side}
          sideOffset={sideOffset}
          variant={menuVariant}
        >
          <Menu.Trigger>{trailingWithProps}</Menu.Trigger>
          {menuContentWithProps}
        </Menu>
      </StyledSplitButton>
    );
  },
);

SplitButtonRoot.displayName = "SplitButton";

const SplitButtonLeading = forwardRef<HTMLButtonElement, SplitButtonLeadingProps>(
  ({ children, ...props }, ref) => {
    return (
      <Button ref={ref} {...props}>
        {children}
      </Button>
    );
  },
);

SplitButtonLeading.displayName = "SplitButton.Leading";

const SplitButtonTrailing = forwardRef<HTMLButtonElement, SplitButtonTrailingProps>(
  ({ children, "aria-label": ariaLabel, ...props }, ref) => {
    return (
      <Button ref={ref} aria-label={ariaLabel || "More actions"} {...props}>
        {children || <ChevronDown />}
      </Button>
    );
  },
);

SplitButtonTrailing.displayName = "SplitButton.Trailing";

const SplitButtonMenuContent = (props: SplitButtonMenuContentProps) => {
  // This component is a placeholder for props. The actual rendering is done in SplitButtonRoot.
  // The props are passed to Menu.Content there.
  return <>{props.children}</>;
};

SplitButtonMenuContent.displayName = "SplitButton.MenuContent";

const SplitButtonMenuItem = forwardRef<HTMLDivElement, SplitButtonMenuItemProps>(
  ({ children, ...props }, ref) => {
    return (
      <Menu.Item ref={ref} {...props}>
        {children}
      </Menu.Item>
    );
  },
);

SplitButtonMenuItem.displayName = "SplitButton.MenuItem";

const SplitButton = Object.assign(SplitButtonRoot, {
  Leading: SplitButtonLeading,
  Trailing: SplitButtonTrailing,
  MenuContent: SplitButtonMenuContent,
  MenuItem: SplitButtonMenuItem,
});

export default SplitButton;
